# Transactional checkout with inventory decrement
@transaction.atomic
def place_order(user, cart):
    order = Order.objects.create(user=user, total=cart.total)
    for item in cart.items.select_related('product'):
        Product.objects.filter(pk=item.product.pk)\
            .update(inventory=F('inventory') - item.qty)
        OrderItem.objects.create(order=order, **item.snapshot)
